def transform(grid):
    g=[row[:] for row in grid]
    color=next(v for v in set(sum(grid,[])) if v not in (next(iter(set(sum(grid,[])))),)) if False else None
    # Complete straight runs of the non-background outline color between its existing marks.
    from collections import Counter
    bg=Counter(sum(grid,[])).most_common(1)[0][0]
    marks=[v for v in Counter(sum(grid,[])) if v!=bg]
    c=marks[0]
    h,w=len(g),len(g[0])
    for r in range(h):
        xs=[x for x in range(w) if grid[r][x]==c]
        if len(xs)>=2:
            for x in range(min(xs),max(xs)+1):
                if g[r][x]==bg: g[r][x]=2
    for x in range(w):
        ys=[r for r in range(h) if grid[r][x]==c]
        if len(ys)>=2:
            for r in range(min(ys),max(ys)+1):
                if g[r][x]==bg: g[r][x]=2
    return g
